-- nine_intro.lua | Luau para ejecutor (móvil y PC)
-- Fase 1: pantalla negra cinematográfica con frases que aparecen escritas, con sonido.
-- Fase 2: NINEHUB con gorros navideños azules. Toca DOS veces la pantalla para saltar.
local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local UIS = game:GetService("UserInputService")
local lp = Players.LocalPlayer

-- Audio incluido en el script: se escribe solo en workspace al ejecutar
