    "VVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVVV"
}
local B64_ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function b64decode(s)
    local map = {}
    for i = 1, 64 do map[string.byte(B64_ALPHA, i)] = i - 1 end
    local out, n = {}, 0
    for i = 1, #s, 4 do
        local a, b, c, d = string.byte(s, i, i + 3)
        local v = (map[a] or 0) * 262144 + (map[b] or 0) * 4096 + (map[c] or 0) * 64 + (map[d] or 0)
        local b1, b2, b3 = math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256
        n = n + 1
        if d == 61 and c == 61 then out[n] = string.char(b1)
        elseif d == 61 then out[n] = string.char(b1, b2)
        else out[n] = string.char(b1, b2, b3) end
    end
    return table.concat(out)
end
AUDIO_WRITE_ERR = nil
if typeof(writefile) == "function" then
    local ok, err = pcall(function() writefile(AUDIO_NAME, b64decode(table.concat(AUDIO_B64))) end)
    if not ok then AUDIO_WRITE_ERR = tostring(err) end
else
    AUDIO_WRITE_ERR = "tu ejecutor no tiene writefile"
end

local CONFIG = {
    Title = "NINEHUB",

    -- Audio: archivo local en la carpeta workspace del ejecutor (nil = no usar)
    IntroSoundFile = "nine_intro.mp3",
    IntroSoundId = nil,        -- alternativa: ID de Roblox (número)
    IntroSoundStart = 0,       -- segundo del audio donde empieza
    IntroSoundLength = nil,    -- segundos que suena; nil = hasta el final de la intro
    SoundVolume = 1,

    -- Frases de la fase 1. Escríbelas tú:
    --   t = segundo (desde que arranca la intro) en que aparece
    --   hold = cuánto se queda visible, type = cuánto tarda en escribirse
    --   y = altura en pantalla (0 arriba, 1 abajo), size = tamaño del texto
    Lines = {
        {t = 0.5, hold = 2.5, type = 1.0, y = 0.28, size = 38, text = "ESCRIBE AQUÍ TU FRASE"},
    },
    LyricsSeconds = 8,         -- duración total de la fase 1

    LetterDelay = 0.35,
    TitleHold = 3.2,
    SnowFlakes = 55,
    SkipTapWindow = 0.45,      -- segundos entre los dos toques
    GuiName = "NineIntro",
}

local C = {
    black = Color3.fromRGB(4, 5, 10),
    bgTop = Color3.fromRGB(10, 45, 160),
    bgBottom = Color3.fromRGB(30, 160, 255),
    glow = Color3.fromRGB(0, 230, 255),
    red = Color3.fromRGB(255, 35, 60),
    white = Color3.fromRGB(255, 255, 255),
    dim = Color3.fromRGB(170, 185, 210),
}

local function mk(class, props, kids)
    local i = Instance.new(class)
    for k, v in pairs(props) do i[k] = v end
    for _, k in ipairs(kids or {}) do k.Parent = i end
    return i
end
local function corner(r) return mk("UICorner", {CornerRadius = r}) end

local function resolveSound()
    if CONFIG.IntroSoundFile then
        local fn = getcustomasset or getsynasset
        if typeof(fn) ~= "function" then
            return nil, "tu ejecutor no tiene getcustomasset"
        end
        if typeof(isfile) == "function" and not isfile(CONFIG.IntroSoundFile) then
            return nil, "no existe en workspace: " .. CONFIG.IntroSoundFile
        end
        local ok, res = pcall(fn, CONFIG.IntroSoundFile)
        if ok then return res end
        return nil, tostring(res)
    elseif CONFIG.IntroSoundId then
        return "rbxassetid://" .. tostring(CONFIG.IntroSoundId)
    end
    return nil
end

local function build()
    local parent = (typeof(gethui) == "function" and gethui()) or lp:WaitForChild("PlayerGui")
    local old = parent:FindFirstChild(CONFIG.GuiName)
    if old then old:Destroy() end

    local gui = mk("ScreenGui", {
        Name = CONFIG.GuiName, ResetOnSpawn = false, IgnoreGuiInset = true,
        DisplayOrder = 999, Parent = parent})

    local conns = {}
    local skipped = false
    local lastTap = -10
    table.insert(conns, UIS.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
            local now = os.clock()
            if now - lastTap <= CONFIG.SkipTapWindow then skipped = true end
            lastTap = now
        end
    end))

    local function sleep(sec)
        local t0 = os.clock()
        while os.clock() - t0 < sec and not skipped do task.wait(0.03) end
    end

    local root = mk("CanvasGroup", {
        Size = UDim2.fromScale(1, 1), BackgroundColor3 = C.black, BorderSizePixel = 0, Parent = gui})
    local bg = mk("Frame", {
        Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1),
        BackgroundTransparency = 1, BorderSizePixel = 0, Parent = root},
        {mk("UIGradient", {Color = ColorSequence.new(C.bgTop, C.bgBottom), Rotation = 90})})

    -- Partículas (polvo/nieve)
    local rng = Random.new()
    for _ = 1, CONFIG.SnowFlakes do
        local size = rng:NextInteger(2, 7)
        local x = rng:NextNumber(0, 1)
        local flake = mk("Frame", {
            Size = UDim2.fromOffset(size, size), Position = UDim2.fromScale(x, -0.05),
            BackgroundColor3 = C.white, BackgroundTransparency = rng:NextNumber(0.2, 0.7),
            BorderSizePixel = 0, Parent = root}, {corner(UDim.new(1, 0))})
        local dur = rng:NextNumber(5, 10)
        task.delay(rng:NextNumber(0, 5), function()
            if flake.Parent then
                TweenService:Create(flake,
                    TweenInfo.new(dur, Enum.EasingStyle.Linear, Enum.EasingDirection.In, -1),
                    {Position = UDim2.fromScale(x + rng:NextNumber(-0.08, 0.08), 1.05)}):Play()
            end
        end)
    end

    local skipHint = mk("TextLabel", {
        Size = UDim2.new(1, 0, 0, 24), AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 0.97),
        BackgroundTransparency = 1, Text = "TOCA 2 VECES PARA SALTAR", Font = Enum.Font.GothamBold,
        TextSize = 13, TextColor3 = C.dim, TextTransparency = 0.3, ZIndex = 5, Parent = root})

    -- Sonido
    local function audioNote(msg)
        warn("[Nine] " .. msg)
        mk("TextLabel", {
            Size = UDim2.new(1, -24, 0, 40), Position = UDim2.fromOffset(12, 40), BackgroundTransparency = 1,
            Text = "SIN AUDIO: " .. msg, Font = Enum.Font.GothamBold, TextSize = 13, TextWrapped = true,
            TextColor3 = Color3.fromRGB(255, 120, 130), TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 10, Parent = root})
    end

    local sound
    local soundUrl, soundErr = resolveSound()
    if AUDIO_WRITE_ERR then audioNote("escribir audio: " .. AUDIO_WRITE_ERR) elseif soundErr then audioNote(soundErr) end
    if soundUrl then
        sound = mk("Sound", {SoundId = soundUrl, Volume = CONFIG.SoundVolume, Parent = gui})
        task.spawn(function()
            local t0 = os.clock()
            while not sound.IsLoaded and os.clock() - t0 < 8 do task.wait(0.1) end
            if sound.IsLoaded then
                sound.TimePosition = CONFIG.IntroSoundStart
                sound:Play()
                if CONFIG.IntroSoundLength then
                    task.delay(CONFIG.IntroSoundLength, function()
                        if sound and sound.Parent then
                            TweenService:Create(sound, TweenInfo.new(0.6), {Volume = 0}):Play()
                        end
                    end)
                end
            else
                audioNote("el audio no cargó (el motor no lo decodificó)")
            end
        end)
    end

    -- Fase 1: frases escritas
    local function showLine(line)
        local lbl = mk("TextLabel", {
            Size = UDim2.new(0.86, 0, 0, (line.size or 36) + 20), Position = UDim2.fromScale(0.07, line.y or 0.3),
            BackgroundTransparency = 1, Text = line.text, Font = Enum.Font.Garamond,
            TextSize = line.size or 36, TextColor3 = C.white, TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true, MaxVisibleGraphemes = 0, ZIndex = 4, Parent = root},
            {mk("UIStroke", {Color = C.white, Thickness = 1.5, Transparency = 0.85})})
        local n = utf8.len(line.text) or #line.text
        local step = math.max(0.02, (line.type or 0.8) / math.max(n, 1))
        for i = 1, n do
            if skipped then break end
            lbl.MaxVisibleGraphemes = i
            task.wait(step)
        end
        lbl.MaxVisibleGraphemes = -1
        sleep(line.hold or 1.5)
        TweenService:Create(lbl, TweenInfo.new(0.5), {TextTransparency = 1}):Play()
        task.wait(0.55)
        lbl:Destroy()
    end

    local start = os.clock()
    for _, line in ipairs(CONFIG.Lines) do
        while os.clock() - start < line.t and not skipped do task.wait(0.03) end
        if skipped then break end
        task.spawn(showLine, line)
    end
    while os.clock() - start < CONFIG.LyricsSeconds and not skipped do task.wait(0.03) end

    -- Fase 2: NINEHUB con gorros
    skipHint.Visible = false
    TweenService:Create(bg, TweenInfo.new(1.2), {BackgroundTransparency = 0}):Play()

    local viewW = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or 800
    local count = #CONFIG.Title
    local w = math.clamp(math.floor(viewW / (count + 2)), 28, 70)
    local h = math.floor(w * 1.5)

    local row = mk("Frame", {
        Size = UDim2.fromOffset(w * count, h * 2), AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.45), BackgroundTransparency = 1, ZIndex = 6, Parent = root},
        {mk("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            HorizontalAlignment = Enum.HorizontalAlignment.Center,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder})})

    local letters = {}
    for idx = 1, count do
        local ch = string.sub(CONFIG.Title, idx, idx)
        local up = (idx % 2 == 1)
        local baseY = up and -6 or 8
        local tilt = up and -14 or 14

        local cell = mk("CanvasGroup", {
            Size = UDim2.fromOffset(w, h * 2), BackgroundTransparency = 1,
            GroupTransparency = 1, LayoutOrder = idx, Parent = row})
        local letter = mk("TextLabel", {
            Size = UDim2.fromOffset(w, h), AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.5, baseY + 40), BackgroundTransparency = 1,
            Text = ch, Font = Enum.Font.GothamBlack, TextSize = math.floor(w * 1.15),
            TextColor3 = C.white, Parent = cell},
            {mk("UIStroke", {Color = C.glow, Thickness = 3})})

        local hat = mk("Frame", {
            Size = UDim2.fromOffset(w, w), AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.5, baseY - h * 0.38),
            BackgroundTransparency = 1, Rotation = tilt, Parent = cell})
        mk("Frame", {
            Size = UDim2.fromOffset(math.floor(w * 0.78), math.floor(w * 0.72)),
            AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.fromScale(0.5, 0.82),
            BackgroundColor3 = C.red, BorderSizePixel = 0, Parent = hat}, {corner(UDim.new(0.5, 0))})
        mk("Frame", {
            Size = UDim2.fromOffset(math.floor(w * 0.98), math.floor(w * 0.24)),
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.82),
            BackgroundColor3 = C.white, BorderSizePixel = 0, Parent = hat}, {corner(UDim.new(0.5, 0))})
        mk("Frame", {
            Size = UDim2.fromOffset(math.floor(w * 0.26), math.floor(w * 0.26)),
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(up and 0.82 or 0.18, 0.16),
            BackgroundColor3 = C.white, BorderSizePixel = 0, Parent = hat}, {corner(UDim.new(1, 0))})

        letters[idx] = {cell = cell, letter = letter, baseY = baseY}
    end

    for idx = 1, count do
        if skipped then break end
        local l = letters[idx]
        TweenService:Create(l.cell, TweenInfo.new(0.5, Enum.EasingStyle.Quad), {GroupTransparency = 0}):Play()
        TweenService:Create(l.letter, TweenInfo.new(0.55, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
            {Position = UDim2.new(0.5, 0, 0.5, l.baseY)}):Play()
        task.wait(CONFIG.LetterDelay)
    end
    if skipped then
        for _, l in ipairs(letters) do
            l.cell.GroupTransparency = 0
            l.letter.Position = UDim2.new(0.5, 0, 0.5, l.baseY)
        end
    end
    if not skipped then sleep(CONFIG.TitleHold) end

    -- Salida (camino único de cierre)
    local out = TweenInfo.new(0.7)
    if sound then TweenService:Create(sound, out, {Volume = 0}):Play() end
    TweenService:Create(root, out, {GroupTransparency = 1}):Play()
    task.wait(0.75)
    if sound then sound:Stop() sound:Destroy() end
    for _, c in ipairs(conns) do c:Disconnect() end
    gui:Destroy()
end

local ok, err = xpcall(build, function(e) return tostring(e) end)
if not ok then
    warn("[Nine] " .. err)
    local p = (typeof(gethui) == "function" and gethui()) or lp:WaitForChild("PlayerGui")
    local g = mk("ScreenGui", {ResetOnSpawn = false, IgnoreGuiInset = true, Parent = p})
    mk("TextLabel", {
        Size = UDim2.fromOffset(340, 200), Position = UDim2.fromOffset(20, 90),
        BackgroundColor3 = Color3.fromRGB(60, 15, 20), TextColor3 = Color3.new(1, 1, 1),
        TextWrapped = true, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        Text = "Nine intro, error:\n" .. err, Parent = g})
end